package cn.sifangguan.hotelaios.finance;

import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import java.io.*;
import java.nio.*;
import java.nio.charset.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Bounded file parsing; imported formulas are never executed. No external links/macros. */
final class FinanceMigrationParser {
 private FinanceMigrationParser(){}
 static List<Map<String,String>> parse(String filename,byte[] bytes,Map<String,String> mapping){if(bytes.length==0||bytes.length>20*1024*1024)throw bad("迁移文件为空或超过20MB");List<List<String>> table;if(filename.toLowerCase(Locale.ROOT).endsWith(".csv"))table=csv(bytes);else if(filename.toLowerCase(Locale.ROOT).endsWith(".xlsx"))table=xlsx(bytes);else throw bad("迁移仅支持真实UTF-8 CSV或XLSX文件，不接受改扩展名的JSON/旧XLS");if(table.size()<2)throw bad("文件没有数据行");var header=table.getFirst();if(new HashSet<>(header).size()!=header.size()||header.stream().anyMatch(String::isBlank))throw bad("源文件表头为空或重复，不能可靠映射");for(String name:mapping.values())if(!header.contains(name))throw bad("映射表头不存在："+name);var result=new ArrayList<Map<String,String>>();for(int r=1;r<table.size();r++){var line=table.get(r);if(line.stream().allMatch(String::isBlank))continue;if(line.size()>header.size())throw bad("第"+(r+1)+"行列数超过表头");var row=new LinkedHashMap<String,String>();row.put("_row",String.valueOf(r+1));mapping.forEach((field,name)->{int index=header.indexOf(name);row.put(field,index<line.size()?line.get(index).trim():"");});result.add(row);}if(result.size()>10000)throw bad("单批最多10000行");return result;}
 static List<List<String>> csv(byte[] bytes){String text;try{text=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}catch(Exception e){throw bad("CSV必须为UTF-8编码，请从金蝶导出后转换编码且保留票号文本");}if(text.startsWith("\ufeff"))text=text.substring(1);var rows=new ArrayList<List<String>>();var row=new ArrayList<String>();var cell=new StringBuilder();boolean quoted=false,closed=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(quoted){if(c=='"'){if(i+1<text.length()&&text.charAt(i+1)=='"'){cell.append('"');i++;}else{quoted=false;closed=true;}}else cell.append(c);}else if(c=='"'){if(cell.length()!=0||closed)throw bad("CSV引号格式错误");quoted=true;}else if(c==','||c=='\n'||c=='\r'){row.add(cell.toString());cell.setLength(0);closed=false;if(c!=','){if(c=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;rows.add(row);row=new ArrayList<>();if(rows.size()>10001)throw bad("单批最多10000行");}}else{if(closed&&!Character.isWhitespace(c))throw bad("CSV闭引号后包含非法字符");if(!closed)cell.append(c);}if(cell.length()>8000||row.size()>100)throw bad("CSV单元格或列数超过安全上限");}if(quoted)throw bad("CSV引号未闭合");if(cell.length()>0||!row.isEmpty()){row.add(cell.toString());rows.add(row);}return rows;}
 static List<List<String>> xlsx(byte[] bytes){try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(bytes))){if(workbook.getNumberOfSheets()!=1)throw bad("请使用单工作表迁移文件，避免悄悄遗漏其他工作表");if(!workbook.getExternalLinksTable().isEmpty()||workbook.isMacroEnabled())throw bad("不接受含外部链接或宏的迁移文件");var sheet=workbook.getSheetAt(0);if(sheet.getLastRowNum()>10000)throw bad("单批最多10000行");var result=new ArrayList<List<String>>();var format=new DataFormatter(Locale.ROOT);for(int r=0;r<=sheet.getLastRowNum();r++){var source=sheet.getRow(r);var values=new ArrayList<String>();if(source!=null){if(source.getLastCellNum()>100)throw bad("单工作表最多100列");for(int c=0;c<source.getLastCellNum();c++){var cell=source.getCell(c);if(cell!=null&&cell.getCellType()==CellType.FORMULA)throw bad("第"+(r+1)+"行包含公式，请在源文件粘贴为值后再导入");String value=cell==null?"":format.formatCellValue(cell);if(cell!=null&&cell.getCellType()==CellType.NUMERIC){var raw=((org.apache.poi.xssf.usermodel.XSSFCell)cell).getRawValue();if(new java.math.BigDecimal(raw).stripTrailingZeros().precision()>15)throw bad("第"+(r+1)+"行数字超出Excel精度，请将原始完整号码作为文本导出");if(DateUtil.isCellDateFormatted(cell))value=cell.getLocalDateTimeCellValue().toLocalDate().toString();else value=raw;}if(value.length()>8000)throw bad("单元格超过安全长度");values.add(value);}}result.add(values);}return result;}catch(org.springframework.web.server.ResponseStatusException e){throw e;}catch(Exception e){throw bad("XLSX文件结构无效或超过解压安全限制");}}
}
